/**
 * @summary List all resellers
 */
export const getListResellersUrl = (params?: ListResellersParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/resellers?${stringifiedParams}`
    : `/api/resellers`;
};

export const listResellers = async (
  params?: ListResellersParams,
  options?: RequestInit,
): Promise<ResellerWithStats[]> => {
  return customFetch<ResellerWithStats[]>(getListResellersUrl(params), {
    ...options,
    method: "GET",
  });
};

